// node gen-skills.mjs <skills dir> <output .ts>
// Writes `export const SKILL_FILES = { "<skill>": { "SKILL.md": "...", "references/x.md": "..." } }`.
// Same shape as SKILL_FILES in index.html (evals/test/skills-sync.test.mjs keeps skills/ and the
// app in step; this file is generated from skills/).
import fs from 'node:fs';
import path from 'node:path';

const [dir, out] = process.argv.slice(2);
if (!dir || !out) { console.error('usage: node gen-skills.mjs <skills dir> <output.ts>'); process.exit(2); }

const files = {};
for (const name of fs.readdirSync(dir).sort()) {
  if (!fs.statSync(path.join(dir, name)).isDirectory()) continue;
  files[name] = {};
  const walk = (rel) => {
    for (const f of fs.readdirSync(path.join(dir, name, rel)).sort()) {
      const p = rel ? rel + '/' + f : f;
      if (fs.statSync(path.join(dir, name, p)).isDirectory()) walk(p);
      else files[name][p] = fs.readFileSync(path.join(dir, name, p), 'utf8');
    }
  };
  walk('');
}
const body = '// GENERATED by supabase/functions/gen-skills.mjs from skills/. Do not edit; do not commit.\n'
  + 'export const SKILL_FILES: Record<string, Record<string, string>> = ' + JSON.stringify(files, null, 1) + ';\n';
fs.writeFileSync(out, body);
console.log('wrote ' + path.relative(process.cwd(), out) + ' (' + Object.keys(files).join(', ') + ')');
